#!/usr/bin/env bash# run-linux-ebpf-challenge-proof.sh ΓÇö Full Linux + eBPF + SCX#1202 challenge proof (T1ΓÇôT4).set -euo pipefailexport REAL_ONLY=1export ELITE_SRC="${ELITE_SRC:-/opt/elite/src}"export FLOOD_LITE_MODE="${FLOOD_LITE_MODE:-1}"export FLOOD_SAFE_MODE=1GATES_SCX="${ELITE_SRC}/benchmarks/sched-ext-gates"GATES_EBPF="${ELITE_SRC}/benchmarks/ebpf-gates"TIER="${1:-all}"STAMP="$(date -u +%Y%m%d)"EVID="${ELITE_SRC}/docs/evidence/scx-1202/CHALLENGE_PROOF_${STAMP}"mkdir -p "${EVID}"/{tier1,tier2,tier3,tier4}FAIL=0START_TS="$(date +%s)"log() { echo "[challenge] $*" | tee -a "${EVID}/run.log"; }pm2_guard() {  local phase="$1"  bash "${ELITE_SRC}/scripts/contabo/pm2-guard-wrap.sh" "${phase}" challenge-proof 2>/dev/null || true}preflight() {  {    echo "=== CHALLENGE PROOF PREFLIGHT ==="    date -u +%Y-%m-%dT%H:%MZ    hostname    uname -a    grep -E 'CONFIG_SCHED_CLASS_EXT|CONFIG_FUNCTION_TRACER' "/boot/config-$(uname -r)" 2>/dev/null || true    command -v scx_loader 2>/dev/null || find /opt/scx /usr/local/bin "${HOME}/.cargo/bin" -name 'scx_loader' 2>/dev/null | head -1 || echo 'scx_loader=not_in_path'    cat /sys/kernel/debug/sched/ext_server/status 2>/dev/null | head -5 || echo 'ext_server=unknown'    cd "${ELITE_SRC}" && git rev-parse HEAD 2>/dev/null || echo 'commit=unknown'  } | tee "${EVID}/00-preflight.txt"}run_tier1() {  log "=== TIER 1: SCX Core G0-G6 ==="  pm2_guard before  if bash "${GATES_SCX}/rt-guard-pass.sh" 2>&1 | tee "${EVID}/tier1/01-rt-guard-pass.log"; then    LATEST="$(ls -td "${ELITE_SRC}"/scripts/oneclick/results/rt-guard-* 2>/dev/null | grep -v flood | head -1 || true)"    [[ -f "${LATEST}/verdict.txt" ]] && cp "${LATEST}/verdict.txt" "${EVID}/tier1/01-RT_GUARD_PASS.verdict"    if grep -q 'SKIP scx_loader' "${EVID}/tier1/01-rt-guard-pass.log" 2>/dev/null; then      log "WARN G6 SKIP scx_loader ΓÇö run sched-ext-vps-prep.sh scx-loader"    fi  else    log "FAIL rt-guard-pass"    FAIL=$((FAIL + 1))  fi  if RUN_LOCAL=1 bash "${GATES_SCX}/rt-monopolization-repro.sh" 2>&1 | tee "${EVID}/tier1/02-repro.log"; then    LATEST_REPRO="$(ls -td "${ELITE_SRC}"/scripts/oneclick/results/rt-guard-baseline-* 2>/dev/null | head -1 || true)"    [[ -f "${LATEST_REPRO}/verdict.txt" ]] && cp "${LATEST_REPRO}/verdict.txt" "${EVID}/tier1/02-repro.verdict"    grep -E 'STALL_DETECTED|LOADER' "${EVID}/tier1/02-repro.log" | tail -5 >> "${EVID}/tier1/02-repro.verdict" 2>/dev/null || true  else    log "FAIL rt-monopolization-repro"    FAIL=$((FAIL + 1))  fi  pm2_guard after}run_tier2() {  log "=== TIER 2: Andrea A/B + Flood P1-P5 ==="  pm2_guard before  if bash "${GATES_SCX}/prove-scx1202-arighi.sh" 2>&1 | tee "${EVID}/tier2/00-arighi.log"; then    LATEST_ARIGHI="$(ls -td "${ELITE_SRC}"/scripts/oneclick/results/arighi-proof-* 2>/dev/null | head -1 || true)"    [[ -f "${LATEST_ARIGHI}/verdict.txt" ]] && cp "${LATEST_ARIGHI}/verdict.txt" "${EVID}/tier2/ANDREA_PROOF.verdict"    [[ -f "${LATEST_ARIGHI}/ANDREA_PROOF_REPORT.md" ]] && cp "${LATEST_ARIGHI}/ANDREA_PROOF_REPORT.md" "${EVID}/tier2/"    [[ -f "${LATEST_ARIGHI}/arm-c-rt_stall.log" ]] && head -30 "${LATEST_ARIGHI}/arm-c-rt_stall.log" > "${EVID}/tier2/arm-c-rt_stall.log" || true  else    LATEST_ARIGHI="$(ls -td "${ELITE_SRC}"/scripts/oneclick/results/arighi-proof-* 2>/dev/null | head -1 || true)"    [[ -n "${LATEST_ARIGHI}" && -f "${LATEST_ARIGHI}/verdict.txt" ]] && cp "${LATEST_ARIGHI}/verdict.txt" "${EVID}/tier2/ANDREA_PROOF.verdict" || true    [[ -n "${LATEST_ARIGHI}" && -f "${LATEST_ARIGHI}/ANDREA_PROOF_REPORT.md" ]] && cp "${LATEST_ARIGHI}/ANDREA_PROOF_REPORT.md" "${EVID}/tier2/" || true    grep -q 'ANDREA_PROOF_PASS fail=0' "${EVID}/tier2/ANDREA_PROOF.verdict" 2>/dev/null || { log "FAIL prove-scx1202-arighi"; FAIL=$((FAIL + 1)); }  fi  bash "${GATES_SCX}/flood-safe-recovery.sh" 2>/dev/null || true  export FLOOD_OUT="${ELITE_SRC}/scripts/oneclick/results/rt-guard-flood-safe-$(date +%Y%m%d-%H%M%S)"  export FLOOD_SAFE_MODE=1  mkdir -p "${FLOOD_OUT}"  for phase in gate P1 P2 P3 P4 P5; do    log "flood phase ${phase}"    if ! bash "${GATES_SCX}/rt-guard-flood-phase.sh" "${phase}" 2>&1 | tee -a "${EVID}/tier2/flood-${phase}.log"; then      log "FAIL flood ${phase}"      FAIL=$((FAIL + 1))    fi    sleep $([[ "${FLOOD_LITE_MODE:-0}" == "1" ]] && echo 10 || echo 30)  done  if bash "${GATES_SCX}/rt-guard-flood-aggregate.sh" "${FLOOD_OUT}" 2>&1 | tee "${EVID}/tier2/flood-aggregate.log"; then    [[ -f "${FLOOD_OUT}/verdict.txt" ]] && cp "${FLOOD_OUT}/verdict.txt" "${EVID}/tier2/04-FLOOD.verdict"  else    grep -E 'RT_GUARD_FLOOD_PASS|FLOOD_SAFE' "${EVID}/tier2/flood-aggregate.log" | tee "${EVID}/tier2/04-FLOOD.verdict" || true    if ! grep -q 'RT_GUARD_FLOOD_PASS fail=0' "${EVID}/tier2/04-FLOOD.verdict" 2>/dev/null; then      FAIL=$((FAIL + 1))    fi  fi  pm2_guard after}run_tier3() {  log "=== TIER 3: Holy Grail H1-H12 + scheduler matrix ==="  pm2_guard before  FLOOD_DIR="$(ls -td "${ELITE_SRC}"/scripts/oneclick/results/rt-guard-flood-safe-* 2>/dev/null | head -1 || true)"  RT_DIR="$(ls -td "${ELITE_SRC}"/scripts/oneclick/results/rt-guard-* 2>/dev/null | grep -v flood | head -1 || true)"  if bash "${GATES_EBPF}/holy-grail-verify.sh" "${FLOOD_DIR}" "${RT_DIR}" 2>&1 | tee "${EVID}/tier3/02-holy-grail.log"; then    grep HOLY_GRAIL "${EVID}/tier3/02-holy-grail.log" | tee "${EVID}/tier3/02-HOLY_GRAIL.verdict" || true  else    grep HOLY_GRAIL "${EVID}/tier3/02-holy-grail.log" 2>/dev/null | tee "${EVID}/tier3/02-HOLY_GRAIL.verdict" || true    if ! grep -q 'HOLY_GRAIL_1202_SOLVED=YES' "${EVID}/tier3/02-HOLY_GRAIL.verdict" 2>/dev/null; then      FAIL=$((FAIL + 1))    fi  fi  export FLOOD_OUT="${FLOOD_DIR}/scheduler-matrix"  mkdir -p "${FLOOD_OUT}"  if [[ "${FLOOD_LITE_MODE:-0}" != "1" ]]; then    if FLOOD_SAFE_MODE=1 bash "${GATES_SCX}/rt-guard-scheduler-matrix.sh" 2>&1 | tee "${EVID}/tier3/scheduler-matrix.log"; then      [[ -f "${FLOOD_OUT}/scheduler-matrix.json" ]] && cp "${FLOOD_OUT}/scheduler-matrix.json" "${EVID}/tier3/" || true    else      log "WARN scheduler-matrix partial"    fi  else    log "tier3 lite ΓÇö skip heavy scheduler-matrix (P5 flood JSON + tier1 repro sufficient)"    [[ -f "${FLOOD_DIR}/scheduler-matrix.json" ]] && cp "${FLOOD_DIR}/scheduler-matrix.json" "${EVID}/tier3/" || true  fi  if [[ "${FLOOD_LITE_MODE:-0}" != "1" ]]; then    export FLOOD_OUT="${FLOOD_DIR}/edge-cases"    mkdir -p "${FLOOD_OUT}"    FLOOD_SAFE_MODE=1 bash "${GATES_SCX}/rt-guard-flood-phase.sh" P4 2>&1 | tee "${EVID}/tier3/edge-cases.log" || log "WARN edge P4"  fi  pm2_guard after}run_tier4() {  log "=== TIER 4: Global eBPF D1-D6 ==="  pm2_guard before  bash "${GATES_EBPF}/global-ebpf-inventory.sh" 2>&1 | tee "${EVID}/tier4/D1-inventory.log" || true  bash "${GATES_EBPF}/telemetry-probe-gate.sh" 2>&1 | tee "${EVID}/tier4/D3-telemetry.log" || log "WARN D3 telemetry"  if [[ -x "${ELITE_SRC}/scripts/oneclick/ebpf-xray-real-proof.sh" ]]; then    bash "${ELITE_SRC}/scripts/oneclick/ebpf-xray-real-proof.sh" 2>&1 | tee "${EVID}/tier4/D4-xray.log" || log "WARN D4 xray"  fi  bash "${GATES_EBPF}/ebpf-future-holes.sh" 2>&1 | tee "${EVID}/tier4/D6-future-holes.log" || true  if bash "${GATES_EBPF}/global-ebpf-aggregate.sh" 2>&1 | tee "${EVID}/tier4/03-global-aggregate.log"; then    grep -E 'GLOBAL_EBPF|fail=0|GLOBAL result=PASS' "${EVID}/tier4/03-global-aggregate.log" | tee "${EVID}/tier4/03-GLOBAL.verdict" || true  else    grep -E 'GLOBAL_EBPF|fail=0|GLOBAL result=PASS' "${EVID}/tier4/03-global-aggregate.log" | tee "${EVID}/tier4/03-GLOBAL.verdict" || true    if ! grep -qE 'fail=0|GLOBAL result=PASS' "${EVID}/tier4/03-GLOBAL.verdict" 2>/dev/null; then      FAIL=$((FAIL + 1))    fi  fi  pm2_guard after}write_summary() {  END_TS="$(date +%s)"  DURATION=$((END_TS - START_TS))  COMMIT_SHA="$(cd "${ELITE_SRC}" && git rev-parse HEAD 2>/dev/null || echo unknown)"  cat > "${EVID}/MANIFEST.json" <<EOF{  "challenge_stamp": "${STAMP}",  "commit_sha": "${COMMIT_SHA}",  "kernel": "$(uname -r)",  "host_class": "Contabo VPS 4vCPU sched_ext",  "real_only": 1,  "duration_sec": ${DURATION},  "tiers": ["T1-SCX-core", "T2-Andrea-flood", "T3-Holy-Grail", "T4-Global-eBPF"]}EOF  cat > "${EVID}/SUMMARY.md" <<SUMMARY# Linux + eBPF + SCX#1202 Challenge Proof**Date:** $(date -u +%Y-%m-%d) **Host:** $(hostname) **Kernel:** $(uname -r)  **Duration:** ${DURATION}s **Commit:** ${COMMIT_SHA}## Verdicts| Tier | Gate | File ||------|------|------|| T1 | RT_GUARD_PASS | tier1/01-RT_GUARD_PASS.verdict || T1 | #1202 repro | tier1/02-repro.verdict || T2 | Andrea A/B | tier2/ANDREA_PROOF.verdict || T2 | Flood P1-P5 | tier2/04-FLOOD.verdict || T3 | Holy Grail H1-H12 | tier3/02-HOLY_GRAIL.verdict || T4 | Global eBPF D1-D6 | tier4/03-GLOBAL.verdict |## Reproduce\`\`\`bashexport REAL_ONLY=1 ELITE_SRC=/opt/elite/srcbash scripts/contabo/run-linux-ebpf-challenge-proof.shbash scripts/verify-scx-1202-evidence.sh\`\`\`## Q&ASee [CHALLENGE_QA_PLAYBOOK.md](CHALLENGE_QA_PLAYBOOK.md)SUMMARY  if [[ "${FAIL}" -eq 0 ]]; then    echo "LINUX_EBPF_CHALLENGE_PASS fail=0 host=$(hostname) kernel=$(uname -r) duration=${DURATION}s" | tee "${EVID}/CHALLENGE_VERDICT.txt"  else    echo "LINUX_EBPF_CHALLENGE_FAIL fail=${FAIL} host=$(hostname) kernel=$(uname -r)" | tee "${EVID}/CHALLENGE_VERDICT.txt"  fi}# --- Main ---preflightcase "${TIER}" in  all)    run_tier1    run_tier2    run_tier3    run_tier4    ;;  1|t1) run_tier1 ;;  2|t2) run_tier2 ;;  3|t3) run_tier3 ;;  4|t4) run_tier4 ;;  *)    echo "Usage: $0 [all|1|2|3|4]" >&2    exit 1    ;;esacwrite_summaryecho "CHALLENGE_EVIDENCE_DIR=${EVID}"echo "=== CHALLENGE VERDICT ==="cat "${EVID}/CHALLENGE_VERDICT.txt"[[ "${FAIL}" -eq 0 ]] || exit 1
